ALTER TABLE organizations ADD COLUMN slug text;
UPDATE organizations o SET slug=CASE WHEN o.id=(SELECT id FROM organizations ORDER BY name,id LIMIT 1) THEN 'club-torneum' ELSE 'org-'||left(o.id::text,8) END;
ALTER TABLE organizations ALTER COLUMN slug SET NOT NULL;
ALTER TABLE organizations ADD UNIQUE(slug);
ALTER TABLE organizations ADD CHECK(slug ~ '^[a-z0-9](-?[a-z0-9])*$');
ALTER TABLE organizations ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE organizations ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE users DROP CONSTRAINT users_email_key;
CREATE UNIQUE INDEX users_org_email ON users(organization_id,lower(email));
ALTER TABLE users ADD UNIQUE(id,organization_id);
CREATE TABLE platform_admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_sessions(token_hash text PRIMARY KEY,admin_id uuid NOT NULL REFERENCES platform_admins ON DELETE CASCADE,expires_at timestamptz NOT NULL);
ALTER TABLE matches ADD UNIQUE(id,organization_id);
ALTER TABLE sponsor_levels ADD UNIQUE(id,organization_id);
ALTER TABLE images ADD UNIQUE(id,organization_id);
-- Composite FKs replace the single-column ones so a row can never reference another organization.
ALTER TABLE sessions DROP CONSTRAINT sessions_user_id_fkey, DROP CONSTRAINT sessions_team_id_fkey, ADD FOREIGN KEY(user_id,organization_id) REFERENCES users(id,organization_id), ADD FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id);
ALTER TABLE verification_tokens DROP CONSTRAINT verification_tokens_team_id_fkey, ADD FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id);
ALTER TABLE result_reports DROP CONSTRAINT result_reports_match_id_fkey, DROP CONSTRAINT result_reports_team_id_fkey, DROP CONSTRAINT result_reports_user_id_fkey, ADD FOREIGN KEY(match_id,organization_id) REFERENCES matches(id,organization_id) ON DELETE CASCADE, ADD FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id), ADD FOREIGN KEY(user_id,organization_id) REFERENCES users(id,organization_id);
ALTER TABLE change_requests DROP CONSTRAINT change_requests_team_id_fkey, ADD FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id);
ALTER TABLE sponsor_levels DROP CONSTRAINT sponsor_levels_tournament_id_fkey, ADD FOREIGN KEY(tournament_id,organization_id) REFERENCES tournaments(id,organization_id);
ALTER TABLE sponsors DROP CONSTRAINT sponsors_tournament_id_fkey, DROP CONSTRAINT sponsors_level_id_fkey, ADD FOREIGN KEY(tournament_id,organization_id) REFERENCES tournaments(id,organization_id), ADD FOREIGN KEY(level_id,organization_id) REFERENCES sponsor_levels(id,organization_id);
ALTER TABLE manual_tiebreaks DROP CONSTRAINT manual_tiebreaks_group_id_fkey, ADD FOREIGN KEY(group_id,organization_id) REFERENCES groups(id,organization_id);
ALTER TABLE images DROP CONSTRAINT images_team_id_fkey, ADD FOREIGN KEY(team_id,organization_id) REFERENCES teams(id,organization_id);
ALTER TABLE teams DROP CONSTRAINT teams_image_id_fkey, ADD FOREIGN KEY(image_id,organization_id) REFERENCES images(id,organization_id);
ALTER TABLE matches DROP CONSTRAINT matches_group_id_fkey, ADD FOREIGN KEY(group_id,organization_id) REFERENCES groups(id,organization_id) ON DELETE CASCADE;
ALTER TABLE schedule_history DROP CONSTRAINT schedule_history_tournament_id_fkey, ADD FOREIGN KEY(tournament_id,organization_id) REFERENCES tournaments(id,organization_id);
ALTER TABLE oauth_states DROP CONSTRAINT oauth_states_user_id_fkey, ADD FOREIGN KEY(user_id,organization_id) REFERENCES users(id,organization_id);
ALTER TABLE messages DROP CONSTRAINT messages_approved_by_fkey, ADD FOREIGN KEY(approved_by,organization_id) REFERENCES users(id,organization_id);
CREATE INDEX audit_org_id ON audit_events(organization_id,id);
